(()=>{const API='/api/creator_tools.php',CSRF=document.querySelector('meta[name="csrf-token"]')?.content||'';const $=s=>document.querySelector(s),screen=$('#screen'),video=$('#video');let stream=null,ws=null,identified=false,seq=0,reqs=new Map(),events=0,streaming=false,recording=false,motion=false,motionTimer=null;const tools=[['🎙️','Voice Cleaner','Управляет шумоподавлением OBS.','mic'],['💬','AI Chat Bot','Ответ зрителю по событию.','chat'],['🛡️','AI Moderator','Проверяет новое сообщение.','moderation'],['🎨','Chat Overlay','Чат поверх OBS Browser Source.','overlay'],['🔔','Smart Alerts','Донаты, подписки и raid-события.','alerts'],['🌍','Live Translator','Перевод выбранной реплики.','translator'],['🔞','Content Censor','Локальный blur чувствительной зоны.','censor'],['✂️','Auto Clips','Отмечает момент для Replay Buffer.','clips'],['🧠','Stream Copilot','Подсказка на событие.','copilot'],['📊','Stream Analytics','Лёгкая статистика сессии.','analytics'],['📝','Stream Summary','Итог завершённого стрима.','summary'],['📱','Shorts Maker','Hook, title и caption после стрима.','shorts']];const state=Object.fromEntries(tools.map(x=>[x[3],false]));
