document.addEventListener('click',e=>{const run=e.target.closest('[data-tool-run]');if(run){const c=run.closest('.card');setTool(c,!state[c.dataset.tool]);if(c.dataset.tool==='mic'&&ws)voiceCleaner(state.mic);if(c.dataset.tool==='clips')clip();if(c.dataset.tool==='overlay')$('#overlay').click();if(c.dataset.tool==='alerts')$('#alert').click();return}const cfg=e.target.closest('[data-config]');if(cfg){cfg.closest('.card').classList.toggle('open');return}});
async function ai(action,text){if(!text)return $('#result').textContent='Введите событие.';$('#result').textContent='AI обрабатывает событие…';try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({action,text,language:$('#lang').value,target_language:$('#target').value})});const j=await r.json();if(!r.ok)throw new Error(j.error||'AI error');$('#result').textContent=j.result||'Готово';log('AI: '+action);if(window.EvruniCreatorBridge?.broadcast)window.EvruniCreatorBridge.broadcast({type:'ai',action,result:j.result||''})}catch(e){$('#result').textContent='Ошибка: '+e.message;log('AI ошибка')}}
const map={chatbot:'chatbot',moderate:'moderation',copilot:'copilot',translate:'translator'};document.querySelectorAll('.ai').forEach(b=>b.onclick=()=>ai(b.dataset.action,$('#event').value.trim()));
async function shareScreen(){if(stream){stopScreen();return}try{stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});video.srcObject=stream;screen.classList.add('live');$('#share').textContent='⏹ Остановить тест';$('#screenStatus').className='status online';$('#screenStatus').innerHTML='<i class="dot"></i> Экран: выбран';log('Запущен тест экрана');stream.getVideoTracks()[0].addEventListener('ended',stopScreen)}catch(e){log('Тест экрана отменён')}}function stopScreen(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}video.srcObject=null;screen.classList.remove('live');$('#share').textContent='▶ Тест экрана';$('#screenStatus').className='status offline';$('#screenStatus').innerHTML='<i class="dot"></i> Экран: не выбран';log('Тест экрана остановлен')}$('#share').onclick=shareScreen;$('#stop').onclick=stopScreen;
$('#blur').onclick=()=>{screen.style.filter=screen.style.filter?'':'blur('+$('#blurRange').value+'px)';log('Censor '+(screen.style.filter?'включён':'выключен'))};$('#overlay').onclick=()=>{screen.classList.toggle('chat-on');$('#overlay').classList.toggle('active');log('Chat Overlay '+(screen.classList.contains('chat-on')?'включён':'выключен'))};$('#alert').onclick=()=>{screen.classList.add('alert');$('#donate').textContent=$('#alertText')?.value||'💰 Донат +500 ₽ · Спасибо!';setTimeout(()=>screen.classList.remove('alert'),Math.max(1000,(Number($('#alertDuration')?.value)||4)*1000));log('Тест доната')};
async function sha256(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return btoa(String.fromCharCode(...new Uint8Array(b)))}async function connectObs(){if(ws){try{ws.close()}catch(_){ }ws=null;identified=false;setObs(false);return}const host=$('#obsHost').value.trim()||'127.0.0.1',port=$('#obsPort').value.trim()||'4455';try{ws=new WebSocket('ws://'+host+':'+port);ws.onmessage=async ev=>{const m=JSON.parse(ev.data);if(m.op===0){const salt=m.d.authenticationSalt,challenge=m.d.challenge,secret=await sha256($('#obsPass').value+salt),auth=await sha256(atob(secret)+challenge);ws.send(JSON.stringify({op:1,d:{rpcVersion:1,authentication:auth}}))}else if(m.op===2){identified=true;setObs(true);getScenes();log('OBS подключён')}else if(m.op===7){const p=reqs.get(m.d.requestId);if(p){reqs.delete(m.d.requestId);m.d.requestStatus?.result?p.resolve(m.d.responseData||{}):p.reject(new Error(m.d.requestStatus?.comment||'OBS request error'))}}else if(m.op===5){const e=m.d.eventType;if(e==='StreamStateChanged'){streaming=!!m.d.eventData.outputActive;syncStream()}if(e==='RecordStateChanged'){recording=!!m.d.eventData.outputActive;syncRecord()}}};ws.onclose=()=>{ws=null;identified=false;setObs(false)};ws.onerror=()=>log('OBS WebSocket ошибка')}catch(e){log('OBS: '+e.message)}}
function req(type,data={}){return new Promise((resolve,reject)=>{if(!ws||!identified)return reject(new Error('OBS не подключён'));const id='ev'+(++seq);reqs.set(id,{resolve,reject});ws.send(JSON.stringify({op:6,d:{requestType:type,requestId:id,requestData:data}}))})}async function getScenes(){try{const r=await req('GetSceneList');const root=$('#obsScenesList');root.innerHTML='';(r.scenes||[]).forEach(s=>{const b=document.createElement('button');b.className='mini scene';b.textContent=s.sceneName;b.onclick=()=>req('SetCurrentProgramScene',{sceneName:s.sceneName}).then(()=>{document.querySelectorAll('.scene').forEach(x=>x.classList.remove('active'));b.classList.add('active');log('Сцена: '+s.sceneName)});root.appendChild(b)})}catch(e){log(e.message)}}function setObs(on){$('#obsStatus').className='status '+(on?'online':'offline');$('#obsStatus').innerHTML='<i class="dot"></i> '+(on?'Подключён':'Не подключён');$('#obsTopStatus').className='status '+(on?'online':'offline');$('#obsTopStatus').innerHTML='<i class="dot"></i> OBS: '+(on?'онлайн':'офлайн');$('#obsConnect').textContent=on?'Отключить OBS':'Подключить OBS'}function syncStream(){const c=$('#obsControls');c.classList.toggle('stream-live',streaming);$('#streamStatus').className='status '+(streaming?'online':'offline');$('#streamStatus').innerHTML='<i class="dot"></i> Эфир: '+(streaming?'онлайн':'офлайн')}function syncRecord(){const c=$('#obsControls');c.classList.toggle('record-live',recording);$('#recordStatus').className='status '+(recording?'online':'offline');$('#recordStatus').innerHTML='<i class="dot"></i> Запись: '+(recording?'идёт':'остановлена')}$('#obsConnect').onclick=connectObs;document.querySelectorAll('.obsbtn').forEach(b=>b.onclick=async()=>{try{await req(b.dataset.req);if(b.dataset.req==='StartStream'){streaming=true;syncStream()}if(b.dataset.req==='StopStream'){streaming=false;syncStream()}if(b.dataset.req==='StartRecord'){recording=true;syncRecord()}if(b.dataset.req==='StopRecord'){recording=false;syncRecord()}log('OBS: '+b.textContent.trim())}catch(e){log('OBS: '+e.message)}});$('#obsScenes').onclick=getScenes;
async function voiceCleaner(on){if(!ws||!identified)return log('Voice Cleaner: сначала подключи OBS');try{const src=$('#obsMic').value.trim();if(!src)throw new Error('Укажи источник микрофона OBS');const list=await req('GetSourceFilterList',{sourceName:src});let f=(list.filters||[]).find(x=>x.filterName==='Evruni Voice Cleaner');if(on&&!f){let kinds=await req('GetSourceFilterKindList');let kind=(kinds.filterKinds||[]).includes('noise_suppress_filter_v2')?'noise_suppress_filter_v2':'noise_suppress_filter';await req('CreateSourceFilter',{sourceName:src,filterName:'Evruni Voice Cleaner',filterKind:kind,filterSettings:{method:'rnnoise',suppress_level:-30}});log('Voice Cleaner: RNNoise добавлен в OBS')}else if(f){await req('SetSourceFilterEnabled',{sourceName:src,filterName:'Evruni Voice Cleaner',filterEnabled:on});log('Voice Cleaner: '+(on?'включён':'выключен'))}}catch(e){log('Voice Cleaner: '+e.message)}}
function clip(){if(!ws||!identified)return log('Auto Clips: подключи OBS');req('SaveReplayBuffer').then(()=>log('Replay Buffer сохранён')).catch(e=>log('Auto Clips: '+e.message))}
const designs={glass:['rgba(5,8,16,.82)','rgba(255,255,255,.1)'],neon:['rgba(32,12,50,.88)','rgba(175,86,255,.25)'],cyan:['rgba(4,30,40,.88)','rgba(77,226,255,.25)'],warm:['rgba(48,27,13,.88)','rgba(255,181,88,.25)']};document.querySelectorAll('.design').forEach(b=>b.onclick=()=>{document.querySelectorAll('.design').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');const d=designs[b.dataset.design];document.querySelectorAll('.chat-bubble').forEach(x=>{x.style.background=d[0];x.style.borderColor=d[1]});log('Дизайн чата: '+b.dataset.design)});$('#chatSize').oninput=e=>document.querySelectorAll('.chat-bubble').forEach(x=>x.style.fontSize=e.target.value+'px');$('#chatOpacity').oninput=e=>document.querySelectorAll('.chat-bubble').forEach(x=>x.style.opacity=e.target.value/100);$('#chatTest').onclick=()=>{$('#chatWindow').scrollTop=0;log('Тест Chat Studio')};$('#chatSave').onclick=()=>{localStorage.setItem('evruni_chat_design',document.querySelector('.design.selected')?.dataset.design||'glass');log('Дизайн чата сохранён')};
let lastX=0,lastY=0;function setMotion(v){const n=Math.max(0,Math.min(100,v));$('#motionMeter').style.width=n+'%';$('#model').style.transform='translateY('+(-n/9)+'px) rotate('+(n/18-2)+'deg) scale('+(1+n/400)+')'}$('#motionStart').onclick=()=>{motion=true;$('#model').classList.add('motion');$('#motionStatus').className='status online';$('#motionStatus').innerHTML='<i class="dot"></i> Motion: онлайн';log('Motion Avatar запущен');if(window.DeviceMotionEvent&&typeof DeviceMotionEvent.requestPermission==='function')DeviceMotionEvent.requestPermission().catch(()=>{})};$('#motionStop').onclick=()=>{motion=false;$('#model').classList.remove('motion');$('#motionStatus').className='status offline';$('#motionStatus').innerHTML='<i class="dot"></i> Motion: офлайн';setMotion(0);if(motionTimer)clearInterval(motionTimer);log('Motion Avatar остановлен')};window.addEventListener('mousemove',e=>{if(!motion)return;const v=Math.min(100,Math.abs(e.clientX-lastX)+Math.abs(e.clientY-lastY)*2);lastX=e.clientX;lastY=e.clientY;setMotion(v*(Number($('#motionSensitivity').value)||5)/5)});window.addEventListener('devicemotion',e=>{if(!motion)return;const a=e.accelerationIncludingGravity||{};const v=Math.min(100,(Math.abs(a.x||0)+Math.abs(a.y||0)+Math.abs(a.z||0))*5);setMotion(v*(Number($('#motionSensitivity').value)||5)/5)});$('#motionCamera').onclick=async()=>{try{const s=await navigator.mediaDevices.getUserMedia({video:{width:320,height:240,frameRate:10},audio:false});s.getTracks().forEach(t=>t.stop());log('Камера motion-теста доступна; поток сразу остановлен')}catch(e){log('Камера: разрешение не дано')}};
function save(){localStorage.setItem('evruni_creator_settings',JSON.stringify({lang:$('#lang').value,target:$('#target').value,blur:$('#blurRange').value,overlay:$('#overlayRange').value}));log('Настройки сохранены')}$('#save').onclick=save;$('#reset').onclick=()=>{localStorage.removeItem('evruni_creator_settings');location.reload()};try{const s=JSON.parse(localStorage.getItem('evruni_creator_settings')||'{}');if(s.lang)$('#lang').value=s.lang;if(s.target)$('#target').value=s.target;if(s.blur)$('#blurRange').value=s.blur;if(s.overlay)$('#overlayRange').value=s.overlay}catch(_){ }
})();
</script><script src="/assets/creator-tools-bridge.js?v=305"></script></body></html>